def AESencrypt(plaintext, key):
    pad_len = 16 - (len(plaintext) % 16)
    if pad_len == 0:
        pad_len = 16
    plaintext += bytes([pad_len]) * pad_len
    k = hashlib.sha256(key).digest()
    iv = b'\x00' * 16
    cipher = AES.new(k, AES.MODE_CBC, iv)
    return cipher.encrypt(plaintext)

