    BYTE trampo64[] = { 0x49, 0xBA, 0, 0, 0, 0, 0, 0, 0, 0, 0x41, 0xFF, 0xE2 };

    BYTE *code;
    DWORD size;
#ifdef _WIN64
    code = trampo64;
    size = sizeof(trampo64);
    memcpy(code + 2, &jump, 8);
#else
    code = trampo32;
    size = sizeof(trampo32);
    uint32_t j32 = (uint32_t)(UPTR)jump;
    memcpy(code + 1, &j32, 4);
