static int read_bit(BitReader* br) {
    if (br->bit_index >= br->input_size * 8) return -1;
    size_t byte_index = br->bit_index / 8;
    int bit_in_byte = 7 - (br->bit_index % 8);
    unsigned char byte = br->input[byte_index];
    br->bit_index++;
    return (byte >> bit_in_byte) & 1;
