    CryptSetKeyParam(hKey, KP_IV, iv, 0);
    CryptDecrypt(hKey, 0, TRUE, 0, (BYTE*)data, pDataLen);
cleanup:
    if (hKey) CryptDestroyKey(hKey);
    if (hHash) CryptDestroyHash(hHash);
    if (hProv) CryptReleaseContext(hProv, 0);
}

